  body=re.search(r'<body[^>]*>',page,re.I);marker=page.find('<site-header ',body.end());require(marker>=body.end(),'Report body boundary changed');after[name]=(page[:body.end()]+notice+'<details id="nfcore-source-review-prior"><summary>Historical catalog checkpoints</summary>'+page[body.end():marker]+'</details>'+page[marker:]).encode()
