 source_names=[source.FOLDER+'/'+n for n in['CENSUS.json','ROLES.json','REVIEW-ENTRIES.json']]+['tools/literature/nfcore_review_roles.py','tools/literature/nfcore_review_source_audit.py'];(folder/'PREVIOUS-SHA256SUMS').write_bytes(previous);(folder/'BASELINE.json').write_bytes(encoded(dict(schema_version=1,archive=pin(folder/'metadata-before.zip'),metadata={name:identity(raw)for name,raw in before.items()},previous_checksums=pin(folder/'PREVIOUS-SHA256SUMS'),transformer=pin(root/'tools/literature/nfcore_review_catalog.py'),source_review_files={name:pin(root/name)for name in source_names})));(out/'PLAN.json').write_bytes(encoded(dict(before={name:identity(raw)for name,raw in before.items()},after={name:identity(raw)for name,raw in after.items()},totals=totals())))
